{
  "qid": "0008_L3_01",
  "sample_id": "0008",
  "gen_prompt": "画哥伦比亚号离开地面设施数秒后的远景全貌；地面设施位于画面下方，采用写实摄影风格。",
  "invocation": "L3",
  "knowledge_dim": "著名航天器识别与任务阶段构型推导",
  "fidelity_checks": [
    {
      "check": "此刻的哥伦比亚号应保持带翼再入载具的整体外形，具有钝头流线机身、前部成组舷窗、大型后掠三角翼和机尾单片垂直尾翼。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "1"
        ],
        "derivation_chain": "题面点名哥伦比亚号且要求描绘其离地数秒后的状态→哥伦比亚号属于美国航天飞机轨道器，离地后不会改变其基本气动构型→画面中的主体应呈现钝头机身、前部舷窗、后掠三角翼与单片垂直尾翼的组合"
      },
      "rubric": {
        "tier_0": "主体缺少带翼轨道器的基本轮廓，或被画成普通飞机、火箭筒体等明显不同构型。",
        "tier_1": "主体可辨为带翼轨道器，但钝头机身、成组舷窗、后掠三角翼或单片垂直尾翼中有一至两项缺失、比例明显失准或辨识含糊。",
        "tier_2": "钝头流线机身、前部多块驾驶舱舷窗、大型后掠三角翼和机尾单片垂直尾翼均清楚成立，整体构型准确可辨。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "主体整体轮廓至少应清楚可辨；远景造成小型舷窗无法逐块点数时，可依据成组深色窗区判定，但若机翼或尾翼被裁出画面则不能判满分。",
      "weight": 1.0
    },
    {
      "check": "若命名标识所在外表面在该视角中清楚可见，应出现可识别的“COLUMBIA”字样。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": "题面点名哥伦比亚号→同型轨道器需要依靠自身命名标识进一步确认身份→当对应外表面可见且具备足够分辨率时，应能读出COLUMBIA"
      },
      "rubric": {
        "tier_0": "对应外表面清楚可见且具备可读尺度，但命名字样缺失、写成其他轨道器名称或出现明显错误拼写。",
        "tier_1": "对应位置存在近似文字标识，但字母局部模糊、缺漏或只能大致辨认为COLUMBIA。",
        "tier_2": "对应外表面上的COLUMBIA字样位置合理且字母完整、清楚可识别。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "仅当命名标识所在外表面可见且图像尺度足以承载可读文字时评分；若因合法视角、距离或烟气遮挡而不可见，本条记为不适用，不得据此扣分。",
      "weight": 1.0
    },
    {
      "check": "离地数秒这一阶段应呈现完整发射组合：轨道器侧挂在一具大型外贮箱上，外贮箱两侧各连接一枚细长的白色固体火箭助推器。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": "题面规定哥伦比亚号刚离开地面设施数秒→此时仍处于以自身主发动机参与的发射初段→轨道器尚未与大型外贮箱和两枚固体火箭助推器分离→画面应呈现轨道器侧挂外贮箱、两侧各一枚助推器的完整组合"
      },
      "rubric": {
        "tier_0": "轨道器被单独画出，或缺少大型外贮箱，或助推器数量明显不是两枚，或各部件关系完全错误。",
        "tier_1": "能够辨认出轨道器、外贮箱和两枚侧置助推器的大致组合，但存在连接关系含糊、左右布局不稳、比例明显失调或一枚助推器被非烟气因素严重画残。",
        "tier_2": "轨道器明确侧挂于一具大型外贮箱，外贮箱左右各有一枚细长白色助推器，数量、相对位置和连接关系均清楚正确；外贮箱采用白色早期涂装或橙色至锈棕色泡沫本色均可。"
      },
      "variants_used": "覆盖外贮箱白色早期涂装，以及橙色或锈棕色泡沫本色",
      "visibility_requirement": "完整组合的上部轮廓和左右两枚助推器必须至少可辨；尾部可被合理的尾焰或烟气部分遮挡，但不能以遮挡掩盖助推器数量和总体连接关系。",
      "weight": 1.0
    },
    {
      "check": "轨道器可见表面应形成明确的明暗热防护分区：机身、机翼上表面和垂直尾翼以白色为主，机腹及机翼下表面则以黑色或深灰色为主。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "4",
          "6"
        ],
        "derivation_chain": "题面点名哥伦比亚号并要求其离地后的外部状态→轨道器不同朝向表面采用不同热防护体系→上部可见外表面以白色为主、腹部和翼下可见区域以深色为主→画面应呈现随视角可见的白色上表面与黑色或深灰色下表面分区"
      },
      "rubric": {
        "tier_0": "轨道器整体采用与规定相反或完全无分区的配色，例如通体深色、通体彩色，或将清楚可见的腹面画成白色而上表面画成黑色。",
        "tier_1": "总体具备白色上部与深色下部的方向性差异，但分界含糊、覆盖范围明显不足，或局部大面积错置。",
        "tier_2": "所有可见区域均遵循正确分区：机身、机翼上表面及垂直尾翼以白色为主，机腹和机翼下表面以黑色或深灰色为主，边界随结构自然变化。"
      },
      "variants_used": "机腹及翼下覆盖黑色热防护表面或深灰色热防护表面均合法",
      "visibility_requirement": "按当前视角实际可见的表面评分；若上表面或下表面之一因合法透视完全不可见，不要求补画隐藏区域，仅核验可见区域，不得因透视缩短造成的分界形变扣分。",
      "weight": 1.0
    },
    {
      "check": "轨道器的钝形机头帽以及可见的两侧机翼前缘应呈黑色或近黑色热防护区域。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": "题面点名处于离地阶段的哥伦比亚号→其轨道器仍保有再入所需的高温热防护布局→迎风位置的机头帽和机翼前缘使用深色热防护材料→可见的机头帽与翼前缘应呈黑色或近黑色"
      },
      "rubric": {
        "tier_0": "清楚可见的机头帽和机翼前缘均未呈现深色热防护区域，或被画成与主体白色表面无区别。",
        "tier_1": "机头帽或机翼前缘中仅一类正确呈深色，或两者均有深色提示但范围零碎、位置偏差明显。",
        "tier_2": "钝形机头帽及所有可见机翼前缘均连续、合理地呈现黑色或近黑色热防护区域。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "机头帽应至少可辨；机翼前缘只核验视角中实际可见部分。透视导致远侧前缘缩短时不扣分，若被合理烟气遮挡则按其余可见部分判断。",
      "weight": 1.0
    },
    {
      "check": "哥伦比亚号轨道器外部不得出现常规喷气式飞机特征，包括发动机进气口、螺旋桨或翼下外挂涡扇发动机吊舱。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": "题面点名哥伦比亚号且处于离地数秒后的任务阶段→其主体是轨道器而非常规大气层喷气客机→不依赖外置进气式航空发动机或螺旋桨推进→轨道器上不得出现进气口、螺旋桨或翼下涡扇吊舱"
      },
      "rubric": {
        "tier_0": "轨道器上出现任一清楚可辨的常规发动机进气口、螺旋桨或翼下外挂涡扇发动机吊舱。",
        "tier_1": "没有完整的错误航空发动机，但局部结构被画得近似进气口或吊舱，形态可疑且容易误读。",
        "tier_2": "轨道器所有可见外表面均未出现进气口、螺旋桨或翼下涡扇吊舱，推进相关结构未被错误画成常规飞机部件。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "核验轨道器所有可见外表面；不得因不可见区域推定存在错误部件。只要任一错误部件清楚可见，即可判0分。",
      "weight": 1.0
    },
    {
      "check": "主体不得被呈现为无翼的钟形或圆锥形返回舱，也不得成为阿波罗式指令舱构型。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "8"
        ],
        "derivation_chain": "题面明确点名哥伦比亚号→哥伦比亚号的主体身份是有翼航天飞机轨道器→其离地阶段也不会转化为传统无翼返回舱→主体不得呈现为钟形、圆锥形或阿波罗式指令舱"
      },
      "rubric": {
        "tier_0": "哥伦比亚号主体被画成无翼钟形、圆锥形或阿波罗式指令舱，或此类舱体取代了轨道器成为主载具。",
        "tier_1": "主体保留部分机翼提示，但整体轮廓过度接近圆锥形返回舱，导致轨道器身份不够明确。",
        "tier_2": "主体明确保持有翼轨道器身份，整体轮廓不属于任何无翼钟形、圆锥形或阿波罗式指令舱构型。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "主体整体轮廓必须可见到足以区分有翼轨道器与无翼返回舱；合理透视缩短机翼时应结合翼根和尾翼判断，不得仅因远侧机翼受遮挡而误判。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "哥伦比亚号应作为远景全貌中的明确主体和主要视觉焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "哥伦比亚号缺失，或被无关元素完全压过而无法辨认为画面主体。",
        "tier_1": "哥伦比亚号在场且大致可辨，但远景尺度过小、位置过偏或背景过于抢眼，主体地位较弱。",
        "tier_2": "在保留远景环境全貌的同时，哥伦比亚号仍清楚可辨并成为主要视觉焦点，主体整体未被画面边缘裁断。"
      }
    },
    {
      "check": "画面应表现哥伦比亚号已经离开地面设施数秒，而非仍停留在地面或处于其他任务阶段。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "主体仍静止停放在地面设施上、已经处于高空巡航状态，或动作阶段与离地数秒明显不符。",
        "tier_1": "主体具有离地趋势，但与地面之间的间隔、运动线索或阶段表现不够明确，需要猜测。",
        "tier_2": "主体整体已与地面设施拉开清楚间隔，并通过位置、尾迹或动态状态明确表现离地数秒的阶段。"
      }
    },
    {
      "check": "地面设施应位于画面下方，与上方的哥伦比亚号形成清楚的二维位置关系。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "地面设施缺失、位于主体上方，或上下关系明显颠倒。",
        "tier_1": "地面设施大致位于下部，但与主体的上下关系含糊或被裁切得难以辨认。",
        "tier_2": "地面设施清楚位于画面下方，哥伦比亚号位于其上方，上下关系明确。"
      }
    },
    {
      "check": "整幅画面应采用写实摄影风格。",
      "facet": "style_control",
      "rubric": {
        "tier_0": "画面呈明显卡通、漫画、扁平插画或其他非摄影风格。",
        "tier_1": "整体趋向写实，但仍有明显插画笔触、三维渲染塑料感或局部风格混杂。",
        "tier_2": "全画一致呈现可信的写实摄影语言，包括自然透视、真实尺度、连续明暗与摄影式细节。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "detail_richness",
    "edge_clarity"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "lighting_atmosphere"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "7",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "8",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "反例自查：题面未限定外贮箱具体年代配色，白色早期涂装与橙色或锈棕色后期外观均被接纳；题面未指定正面、侧面或俯仰视角，命名字样及上下表面检查均设置了不可见处置；各满分档允许透视缩短、远侧遮挡和合理烟气遮挡，不以单张样本图的偶然视角或细节作为约束。"
}
